async function run(wf, args) {
{
  const { prd_dir, design_dir, acceptance_dir } = args;

  const REQUIREMENT_PROMPT = `# Requirement List Review Agent

You are an isolated review subagent. You review the requirements list in \`prd.md\`
for soundness before implementation. You have no prior conversation context — read
the files under the input paths below.

## Focus — check ONLY these two things

1. **Technical feasibility** — is every requirement achievable with the project's
   tech stack (or a reasonable, available addition)? Flag anything impossible,
   speculative, or unsupported by evidence.
2. **Mutual contradiction** — do any two requirements conflict (mutually exclusive),
   or is any single requirement internally inconsistent?

Do not review the architecture (that is the design-review agent's job) or the
acceptance criteria (the acceptance-review agent's job).

## Inputs

- \`prd_dir\` — directory containing \`prd.md\` (the requirements list you review).
- \`design_dir\` — directory containing \`design.md\` (read for context only).
- \`acceptance_dir\` — directory containing \`acceptance.md\` (read for context only).

## Output

Return \`verdict: "pass"\` only if the requirements are sound. Otherwise return
\`verdict: "fail"\` and one \`issues\` entry per finding: cite the requirement id, the
problem, and a suggested fix.

Report your verdict by calling the \`structured_output\` tool exactly once with the
JSON object above. Do NOT finish with a plain-text JSON string or a markdown code
block — only the \`structured_output\` call counts as your result.`;

  const DESIGN_PROMPT = `# Design Review Agent

You are an isolated review subagent. You review the architecture design in
\`design.md\` for over-engineering. You have no prior conversation context — read the
files under the input paths below.

## Focus — check ONLY these things

1. **Over-engineering** — does the design add complexity beyond what the requirements
   demand?
2. **Minimal complexity** — is this the simplest design that still satisfies every
   requirement?
3. **Minimal invasiveness** — does it change existing code in the least invasive way
   possible?
4. **External libraries** — does it introduce necessary libraries that genuinely
   simplify development, and does it AVOID unnecessary ones?

Do not review requirement feasibility (the requirement-list-review agent's job) or
the acceptance criteria (the acceptance-review agent's job).

## Inputs

- \`prd_dir\` — directory containing \`prd.md\` (read for context: the requirements).
- \`design_dir\` — directory containing \`design.md\` (the design you review).
- \`acceptance_dir\` — directory containing \`acceptance.md\` (read for context only).

## Output

Return \`verdict: "pass"\` only if the design is appropriately minimal. Otherwise
return \`verdict: "fail"\` and one \`issues\` entry per finding: cite the module or
decision, the problem (over-engineering, unnecessary complexity, unnecessary
dependency, …), and a suggested simplification.

Report your verdict by calling the \`structured_output\` tool exactly once with the
JSON object above. Do NOT finish with a plain-text JSON string or a markdown code
block — only the \`structured_output\` call counts as your result.`;

  const ACCEPTANCE_PROMPT = `# Acceptance Review Agent

You are an isolated review subagent. You review the acceptance criteria list in
\`acceptance.md\` for clarity and verifiability. You have no prior conversation
context — read the files under the input paths below.

## Focus — check ONLY these things

1. **Clarity** — is every acceptance criterion specific and unambiguous enough that
   a reviewer could decide pass/fail without extra interpretation?
2. **Objective, verifiable evidence** — does every criterion name a concrete,
   checkable piece of evidence (a test, a command output, an observable behavior)?
   Flag any criterion that relies on subjective judgment or has no evidence.

Do not review requirement feasibility (the requirement-list-review agent's job) or
the design (the design-review agent's job).

## Inputs

- \`prd_dir\` — directory containing \`prd.md\` (read for context).
- \`design_dir\` — directory containing \`design.md\` (read for context).
- \`acceptance_dir\` — directory containing \`acceptance.md\` (the list you review).

## Output

Return \`verdict: "pass"\` only if every criterion is clear and verifiable. Otherwise
return \`verdict: "fail"\` and one \`issues\` entry per finding: cite the criterion id,
the problem (unclear / no evidence / subjective), and a suggested fix.

Report your verdict by calling the \`structured_output\` tool exactly once with the
JSON object above. Do NOT finish with a plain-text JSON string or a markdown code
block — only the \`structured_output\` call counts as your result.`;

  const REVIEW_SCHEMA = {
  type: 'object',
  required: ['verdict', 'issues'],
  properties: {
    verdict: { type: 'string', enum: ['pass', 'fail'] },
    issues: { type: 'array', items: { type: 'object', required: ['where', 'problem', 'suggestion'], properties: { where: { type: 'string' }, problem: { type: 'string' }, suggestion: { type: 'string' } } } },
  },
};

  function inputs() {
    return [
      '## Inputs',
      `- prd_dir: ${prd_dir}`,
      `- design_dir: ${design_dir}`,
      `- acceptance_dir: ${acceptance_dir}`,
    ].join('\n');
  }

  const REVIEWERS = [
    { key: 'requirement', label: 'requirement-list-review', prompt: REQUIREMENT_PROMPT, doc: 'prd.md', dir: prd_dir },
    { key: 'design', label: 'design-review', prompt: DESIGN_PROMPT, doc: 'design.md', dir: design_dir },
    { key: 'acceptance', label: 'acceptance-review', prompt: ACCEPTANCE_PROMPT, doc: 'acceptance.md', dir: acceptance_dir },
  ];

  // SINGLE review — dispatch all three axes once, in parallel. No repair agent,
  // no re-review loop: the main agent applies the returned issues itself and may
  // re-run the review as a fresh, independent single pass.
  const results = await wf.phase('plan-review', () => wf.parallel(
    REVIEWERS.map(r => () => wf.runAgent({
      name: r.label,
      prompt: r.prompt + '\n\n' + inputs(),
      readOnly: false,
      modelHint: 'deep',
      outputSchema: REVIEW_SCHEMA,
    })),
  ));

  const passed = [];
  const failures = [];
  let anyNull = false;
  REVIEWERS.forEach((r, i) => {
    const res = results[i];
    if (res === null) {
      anyNull = true;
      return;
    }
    const structured = res.structured;
    if (structured !== undefined && structured.verdict === 'pass') {
      passed.push(r.key);
    } else {
      failures.push({ reviewer: r.key, doc: r.doc, issues: structured?.issues ?? [] });
    }
  });

  // A null reviewer terminates the run as failed WITHOUT listing pass axes (or
  // the null axis itself — its failure is the status, not a verdict-fail row).
  if (anyNull) return { status: 'failed', reason: 'a review agent failed', failures };
  return { status: 'done', pass: failures.length === 0, passed, failures };
}
}
